const commander = require('../');

describe('subcommand name and alias clashes', () => {
  test('when .command() repeats a name then throws', () => {
    const program = new commander.Command();
    program.command('sub');
    expect(() => program.command('sub')).toThrow('cannot add command');
  });

  test('when .addCommand() repeats a name then throws', () => {
    const program = new commander.Command();
    program.command('sub');
    expect(() => program.addCommand(new commander.Command('sub'))).toThrow('cannot add command');
  });

  test('when command name matches existing alias then throws', () => {
    const program = new commander.Command();
    program.command('sub').alias('s');
    expect(() => program.command('s')).toThrow('cannot add command');
  });

  test('when added command alias matches existing name then throws', () => {
    const program = new commander.Command();
    program.command('sub');
    expect(() => program.addCommand(new commander.Command('other').alias('sub'))).toThrow('cannot add command');
  });

  test('when .alias() matches sibling name then throws', () => {
    const program = new commander.Command();
    program.command('a');
    expect(() => program.command('b').alias('a')).toThrow('cannot add alias');
  });

  test('when .alias() matches sibling alias then throws', () => {
    const program = new commander.Command();
    program.command('a').alias('x');
    expect(() => program.command('b').alias('x')).toThrow('cannot add alias');
  });

  test('when .alias() on executable subcommand matches sibling then throws', () => {
    const program = new commander.Command();
    program.command('a', 'desc');
    expect(() => program.command('b', 'desc').alias('a')).toThrow('cannot add alias');
  });

  test('when names and aliases are distinct then no error', () => {
    const program = new commander.Command();
    program.command('a').alias('x');
    program.command('b').alias('y');
    program.addCommand(new commander.Command('c').alias('z'));
    expect(program.commands.length).toBe(3);
  });
});
